    67	    await consumeRateLimit(ORG_A, "member:invite");
    68	    vi.advanceTimersByTime(24 * 60 * 60_000);
    69	
    70	    const verdict = await consumeRateLimit(ORG_A, "member:invite");
    71	    expect(verdict.remaining).toBe(getBucketConfig("member:invite").capacity - 1);
    72	  });
