    75	    const verdict = await consumeRateLimit(ORG_A, "member:invite", 5);
    76	    expect(verdict.allowed).toBe(true);
    77	    expect(verdict.remaining).toBe(15);
    78	  });
    79	
    80	  it("refuses a cost larger than the bucket without spending tokens", async () => {
    81	    const denied = await consumeRateLimit(ORG_A, "auth:password-reset", 999);
    82	    expect(denied.allowed).toBe(false);
    83	    expect(denied.remaining).toBe(getBucketConfig("auth:password-reset").capacity);
    84	  });
    85	
    86	  it("keeps buckets separate per org and per key", async () => {
    87	    const capacity = getBucketConfig("auth:password-reset").capacity;
    88	    for (let i = 0; i < capacity; i += 1) {
    89	      await consumeRateLimit(ORG_A, "auth:password-reset");
    90	    }
    91	
    92	    expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(false);
    93	    expect((await consumeRateLimit(ORG_B, "auth:password-reset")).allowed).toBe(true);
    94	    expect((await consumeRateLimit(ORG_A, "member:invite")).allowed).toBe(true);
