   103	      getPlanLimits("free").apiRequestsPerHour,
   104	    );
   105	    expect(growth.remaining).toBeGreaterThan(free.remaining);
   106	  });
   107	
   108	  it("reports a resetAt in the future when the bucket is empty", async () => {
   109	    const capacity = getBucketConfig("auth:password-reset").capacity;
   110	    for (let i = 0; i < capacity; i += 1) {
   111	      await consumeRateLimit(ORG_A, "auth:password-reset");
   112	    }
   113	
