/**
 * Single use: the update only matches a token nobody has spent yet, so of two
 * racing submissions of one link, only the first gets `true`.
 */
export async function consumeResetToken(id: string): Promise<boolean> {
  const stamp = toIsoTimestamp(new Date());
  const result = getDb()
    .update(passwordResetTokens)
    .set({ usedAt: stamp, updatedAt: stamp })
    .where(
      and(eq(passwordResetTokens.id, id), isNull(passwordResetTokens.usedAt)),
    )
    .run();
  return result.changes === 1;
}

