/** Buckets guarding the unauthenticated endpoints; each is split per address. */
const LOGIN_BUCKET = "auth:login";
const RESET_BUCKET = "auth:password-reset";

/**
 * Rate limiting before a session exists has no tenant to charge against, so
 * every unauthenticated attempt is billed to this sentinel org. The address in
 * the bucket key is what tells one account's allowance from another's.
 */
const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

/**
 * How long a password-reset link stays usable after it is sent. It is also
 * spent on first use, so a link works once, for an hour.
 */
const RESET_TTL_MS = 60 * 60 * 1000;

