import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";
import { hashPassword } from "@/lib/hash";
import { getBucketConfig, resetRateLimits } from "@/lib/rate-limit";
import * as authService from "@/server/services/auth-service";
import * as userRepo from "@/server/repositories/user-repository";
import {
  createSessionToken,
  destroySession,
  resolveSession,
} from "@/server/services/session-service";
import { resetTestDb, setupTestDb } from "./helpers/db";

const captured = vi.hoisted(() => ({ tokens: [] as string[] }));

vi.mock("@/server/services/email-service", async (importOriginal) => {
  const actual = await importOriginal<typeof import("@/server/services/email-service")>();
  return {
    ...actual,
    renderEmail: vi.fn(async (template: string, props: Record<string, unknown>) => {
      if (template === "password-reset") captured.tokens.push(String(props.token));
      return { subject: "s", html: "<p>h</p>", text: "h" };
    }),
    sendEmail: vi.fn(async () => undefined),
  };
});

const PASSWORD = "Correct1Horse2";
const NEW_PASSWORD = "Another1Horse2";
const HOUR = 60 * 60 * 1000;
const START = "2026-10-08T12:00:00.000Z";

beforeAll(async () => {
  await setupTestDb();
});

beforeEach(async () => {
  await resetTestDb();
  resetRateLimits();
  captured.tokens.length = 0;
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(new Date(START));
});

afterEach(() => {
  vi.useRealTimers();
});

async function makeUser(email: string) {
  return userRepo.insertUser({
    email,
    name: "Test User",
    passwordHash: await hashPassword(PASSWORD),
  });
}

function login(email: string, password = PASSWORD, rememberMe = false) {
  return authService.login({ email, password, rememberMe });
}

function reset(token: string, password = NEW_PASSWORD) {
  return authService.confirmPasswordReset({
    token,
    password,
    confirmPassword: password,
  });
}

describe("sign-out", () => {
  it("ends only the session that signed out", async () => {
    await makeUser("alice@example.com");
    await makeUser("bob@example.com");
    const a1 = (await login("alice@example.com")).token;
    const a2 = (await login("alice@example.com")).token;
    const b1 = (await login("bob@example.com")).token;

    await destroySession(a1);

    expect(await resolveSession(a1)).toBeNull();
    expect(await resolveSession(a2)).not.toBeNull();
    expect(await resolveSession(b1)).not.toBeNull();
  });

  it("is harmless for unknown or already-ended sessions", async () => {
    await makeUser("alice@example.com");
    const token = (await login("alice@example.com")).token;
    await destroySession(token);
    await expect(destroySession(token)).resolves.toBeUndefined();
    await expect(destroySession("never-issued-token-0000000000")).resolves.toBeUndefined();
  });

  it("lets a fresh sign-in start a new session", async () => {
    await makeUser("alice@example.com");
    const first = (await login("alice@example.com")).token;
    await destroySession(first);
    const second = (await login("alice@example.com")).token;
    expect(second).not.toBe(first);
    expect(await resolveSession(second)).not.toBeNull();
  });
});

describe("session lifetime", () => {
  it("lasts 24 hours without remember me", async () => {
    const user = await makeUser("alice@example.com");
    const { token } = await login("alice@example.com");
    const principal = await resolveSession(token);
    expect(new Date(principal!.expiresAt).getTime()).toBe(Date.now() + 24 * HOUR);
    expect(user.id).toBeTruthy();
  });

  it("lasts 30 days with remember me", async () => {
    await makeUser("alice@example.com");
    const { token } = await login("alice@example.com", PASSWORD, true);
    const principal = await resolveSession(token);
    expect(new Date(principal!.expiresAt).getTime()).toBe(Date.now() + 30 * 24 * HOUR);
  });

  it("is refused once its lifetime has passed", async () => {
    await makeUser("alice@example.com");
    const { token } = await login("alice@example.com");
    vi.setSystemTime(new Date(Date.parse(START) + 24 * HOUR + 60_000));
    expect(await resolveSession(token)).toBeNull();
  });

  it("createSessionToken defaults to 24 hours", async () => {
    const user = await makeUser("alice@example.com");
    const { expiresAt } = await createSessionToken(user.id);
    expect(new Date(expiresAt).getTime()).toBe(Date.now() + 24 * HOUR);
  });
});

describe("password reset", () => {
  it("is usable at 59 minutes", async () => {
    await makeUser("alice@example.com");
    await authService.requestPasswordReset({ email: "alice@example.com" });
    vi.setSystemTime(new Date(Date.parse(START) + 59 * 60_000));
    await expect(reset(captured.tokens[0]!)).resolves.toBeDefined();
  });

  it("is refused at 61 minutes", async () => {
    await makeUser("alice@example.com");
    await authService.requestPasswordReset({ email: "alice@example.com" });
    vi.setSystemTime(new Date(Date.parse(START) + 61 * 60_000));
    await expect(reset(captured.tokens[0]!)).rejects.toThrow();
  });

  it("works only once", async () => {
    await makeUser("alice@example.com");
    await authService.requestPasswordReset({ email: "alice@example.com" });
    await reset(captured.tokens[0]!);
    await expect(reset(captured.tokens[0]!)).rejects.toThrow();
  });

  it("a new request retires the earlier link of the same account", async () => {
    await makeUser("alice@example.com");
    await authService.requestPasswordReset({ email: "alice@example.com" });
    await authService.requestPasswordReset({ email: "alice@example.com" });
    expect(captured.tokens).toHaveLength(2);
    await expect(reset(captured.tokens[0]!)).rejects.toThrow();
    await expect(reset(captured.tokens[1]!)).resolves.toBeDefined();
  });

  it("a new request does not retire another account's link", async () => {
    await makeUser("alice@example.com");
    await makeUser("bob@example.com");
    await authService.requestPasswordReset({ email: "alice@example.com" });
    await authService.requestPasswordReset({ email: "bob@example.com" });
