  vi.setSystemTime(new Date(START));
});

afterEach(() => {
  vi.useRealTimers();
});

async function makeUser(email: string) {
  return userRepo.insertUser({
    email,
    name: "Test User",
    passwordHash: await hashPassword(PASSWORD),
  });
}

function login(email: string, password = PASSWORD, rememberMe = false) {
  return authService.login({ email, password, rememberMe });
}

function reset(token: string, password = NEW_PASSWORD) {
  return authService.confirmPasswordReset({
    token,
    password,
    confirmPassword: password,
  });
}

describe("sign-out", () => {
  it("ends only the session that signed out", async () => {
    await makeUser("alice@example.com");
    await makeUser("bob@example.com");
    const a1 = (await login("alice@example.com")).token;
    const a2 = (await login("alice@example.com")).token;
    const b1 = (await login("bob@example.com")).token;

    await destroySession(a1);

    expect(await resolveSession(a1)).toBeNull();
    expect(await resolveSession(a2)).not.toBeNull();
    expect(await resolveSession(b1)).not.toBeNull();
  });

  it("is harmless for unknown or already-ended sessions", async () => {
    await makeUser("alice@example.com");
    const token = (await login("alice@example.com")).token;
    await destroySession(token);
    await expect(destroySession(token)).resolves.toBeUndefined();
    await expect(destroySession("never-issued-token-0000000000")).resolves.toBeUndefined();
  });

  it("lets a fresh sign-in start a new session", async () => {
    await makeUser("alice@example.com");
    const first = (await login("alice@example.com")).token;
    await destroySession(first);
    const second = (await login("alice@example.com")).token;
    expect(second).not.toBe(first);
    expect(await resolveSession(second)).not.toBeNull();
  });
});

describe("session lifetime", () => {
  it("lasts 24 hours without remember me", async () => {
    const user = await makeUser("alice@example.com");
    const { token } = await login("alice@example.com");
    const principal = await resolveSession(token);
    expect(new Date(principal!.expiresAt).getTime()).toBe(Date.now() + 24 * HOUR);
